import React, { useState, useRef, useEffect } from 'react';
import { getProductImage } from '../data/menuData';

const weightLabels = { "1KG": "1 KG", "1/2KG": "½ KG", "250GM": "250 GM" };

function ProductCard({ product, onAddToCart }) {
  const [selectedWeight, setSelectedWeight] = useState("1KG");
  const [isHovered, setIsHovered] = useState(false);
  const [added, setAdded] = useState(false);
  const [imgError, setImgError] = useState(false);
  const [imgLoaded, setImgLoaded] = useState(false);
  const [tilt, setTilt] = useState({ rotateX: 0, rotateY: 0 });
  const cardRef = useRef(null);
  const [isVisible, setIsVisible] = useState(false);

  // Intersection Observer for scroll animation
  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.1 }
    );
    if (cardRef.current) observer.observe(cardRef.current);
    return () => observer.disconnect();
  }, []);

  // 3D Tilt Effect
  const handleMouseMove = (e) => {
    if (!cardRef.current) return;
    const rect = cardRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const centerX = rect.width / 2;
    const centerY = rect.height / 2;
    const rotateX = ((y - centerY) / centerY) * -8;
    const rotateY = ((x - centerX) / centerX) * 8;
    setTilt({ rotateX, rotateY });
  };

  const handleMouseLeave = () => {
    setTilt({ rotateX: 0, rotateY: 0 });
    setIsHovered(false);
  };

  const handleAdd = () => {
    onAddToCart(product, selectedWeight);
    setAdded(true);
    setTimeout(() => setAdded(false), 1200);
  };

  return (
    <div
      ref={cardRef}
      className={`group bg-white rounded-2xl overflow-hidden shadow-lg hover:shadow-2xl transition-all duration-500 ease-out ${
        isHovered ? 'scale-[1.03] -translate-y-2' : ''
      } ${isVisible ? 'animate-fade-in-up opacity-100' : 'opacity-0'}`}
      style={{
        transform: isHovered ? `perspective(1000px) rotateX(${tilt.rotateX}deg) rotateY(${tilt.rotateY}deg)` : '',
        transition: 'transform 0.2s ease-out, opacity 0.6s ease-out, box-shadow 0.3s ease',
        animationDelay: `${(product.id % 10) * 0.05}s`,
        boxShadow: isHovered 
          ? '0 20px 50px rgba(128,0,32,0.2), 0 0 0 1px rgba(212,160,23,0.15)' 
          : '0 4px 15px rgba(0,0,0,0.08)'
      }}
      onMouseEnter={() => setIsHovered(true)}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
    >
      {/* Image with gradient overlay and shimmer */}
      <div className={`relative h-48 overflow-hidden bg-gradient-to-br ${product.bgColor || 'from-orange-100 to-amber-100'}`}>
        {!imgError ? (
          <>
            {!imgLoaded && (
              <div className="absolute inset-0 image-shimmer z-10"></div>
            )}
            <img
              src={getProductImage(product)}
              alt={product.name}
              className={`w-full h-full object-cover transition-all duration-700 ${isHovered ? 'scale-110' : 'scale-100'} ${imgLoaded ? 'opacity-100' : 'opacity-0'}`}
              loading="lazy"
              onLoad={() => setImgLoaded(true)}
              onError={() => { setImgError(true); setImgLoaded(true); }}
            />
          </>
        ) : (
          <div className={`w-full h-full bg-gradient-to-br ${product.bgColor || 'from-orange-100 to-amber-100'} flex items-center justify-center`}>
            <span className="text-6xl opacity-40 animate-float">{product.emoji || '🍽️'}</span>
          </div>
        )}
        {/* Gradient overlay */}
        <div className={`absolute inset-0 bg-gradient-to-t from-black/50 via-black/10 to-transparent transition-opacity duration-300 ${isHovered ? 'opacity-100' : 'opacity-70'}`}></div>
        
        {/* Category badge */}
        <span className="absolute top-3 left-3 bg-white/90 backdrop-blur-sm px-3 py-1 rounded-full text-xs font-semibold text-gray-700 shadow-lg hover:scale-105 transition-transform">
          {product.category}
        </span>
        
        {/* Out of stock badge */}
        {!product.in_stock !== false && !product.in_stock && (
          <span className="absolute top-3 right-3 bg-red-500 text-white px-3 py-1 rounded-full text-xs font-bold shadow-lg animate-pulse">
            Out of Stock
          </span>
        )}
        
        {/* Price badge overlay on hover */}
        <div className={`absolute bottom-2 right-2 transition-all duration-300 ${isHovered ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-2'}`}>
          <span className="bg-white/90 backdrop-blur-sm px-3 py-1.5 rounded-full text-sm font-bold shadow-lg" style={{ color: 'var(--maroon)' }}>
            ₹{product.prices[selectedWeight]}/{weightLabels[selectedWeight]}
          </span>
        </div>
      </div>

      {/* Content */}
      <div className="p-4 relative">
        <h3 className="text-lg font-bold text-gray-800 mb-3 transition-colors" style={{ color: isHovered ? 'var(--maroon)' : '#1F2937' }}>
          {product.name}
          {isHovered && <span className="inline-block ml-1 animate-bounce-in">✨</span>}
        </h3>

        {/* Weight Selector - All 3 tiers */}
        <div className="flex gap-1.5 mb-3">
          {Object.entries(product.prices).map(([weight, price], index) => (
            <button
              key={weight}
              onClick={() => setSelectedWeight(weight)}
              className={`flex-1 py-2 px-1 rounded-lg text-xs font-semibold transition-all duration-200 ${
                selectedWeight === weight
                  ? 'bg-gradient-to-r from-[var(--maroon)] to-[var(--saffron)] text-white shadow-lg scale-105'
                  : 'bg-gray-100 text-gray-600 hover:bg-[var(--saffron-light)] hover:text-white'
              }`}
              style={{
                animationDelay: `${index * 0.05}s`,
                transform: selectedWeight === weight ? 'scale(1.05)' : 'scale(1)'
              }}
            >
              <div>{weightLabels[weight]}</div>
              <div className="mt-0.5">₹{price}</div>
            </button>
          ))}
        </div>

        {/* Highlighted selected price */}
        <div className="flex items-center justify-between mb-3 rounded-lg px-3 py-2 border transition-all duration-300" 
          style={{ 
            background: isHovered ? 'linear-gradient(135deg, var(--saffron-light), var(--gold-light))' : 'linear-gradient(135deg, var(--saffron-light)/20, var(--cream))',
            borderColor: isHovered ? 'var(--gold)' : 'var(--gold-light)/30'
          }}>
          <span className="text-sm font-medium" style={{ color: isHovered ? 'var(--maroon)' : '#4B5563' }}>{weightLabels[selectedWeight]}</span>
          <div className="flex items-center gap-2">
            <span className="text-xs text-gray-400 line-through">₹{product.prices[selectedWeight] + Math.round(product.prices[selectedWeight] * 0.1)}</span>
            <span className="text-xl font-bold" style={{ color: 'var(--maroon)' }}>₹{product.prices[selectedWeight]}</span>
          </div>
        </div>

        {/* Add to Cart */}
        <button
          onClick={handleAdd}
          disabled={added || !product.in_stock}
          className={`w-full py-3 rounded-xl font-bold text-sm transition-all duration-300 relative overflow-hidden ${
            added
              ? 'bg-green-500 text-white scale-105 shadow-lg'
              : !product.in_stock
                ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                : isHovered
                  ? 'text-white shadow-lg'
                  : 'bg-gray-100 text-gray-700'
          }`}
          style={{
            background: !added && product.in_stock !== false
              ? isHovered 
                ? 'linear-gradient(135deg, var(--maroon), var(--saffron))'
                : ''
              : undefined,
            boxShadow: isHovered && !added && product.in_stock !== false
              ? '0 8px 25px rgba(128,0,32,0.3)'
              : undefined
          }}
        >
          {/* Ripple effect container */}
          <span className="flex items-center justify-center gap-2 relative z-10">
            {added ? (
              <>
                <span className="inline-block animate-bounce-in">✅</span>
                <span>Added!</span>
              </>
            ) : !product.in_stock ? (
              '❌ Unavailable'
            ) : (
              <>
                <span>🛒</span>
                <span>Add to Cart</span>
                {isHovered && <span className="inline-block animate-bounce">→</span>}
              </>
            )}
          </span>
          {/* Background shimmer on hover */}
          {isHovered && !added && product.in_stock !== false && (
            <span className="absolute inset-0 bg-white/10 shimmer"></span>
          )}
        </button>
      </div>
    </div>
  );
}

export default ProductCard;
